/* EcoSenseMonitor Web 3.5 — real client-side functionality; remote sync requires servidor central API deployment. */
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], F=n=>Number.isFinite(Number(n))?Number(n):null;
const html=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const unit=(n,u='',d=1)=>n==null||!Number.isFinite(+n)?'—':Number(n).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d})+u;
const dateFmt=t=>{if(!t)return '—';let d=new Date(t);return Number.isNaN(+d)?'Data inválida':d.toLocaleString('pt-BR',{timeZone:'America/Fortaleza',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})};
const CENTRAL_API=(window.ECOSENSE_API_URL||'').trim().replace(/\/$/,'');
const STORE='ecosense_web_35';let state={stations:[],readings:{},events:[],apiUrl:'',adminKey:'',theme:'dark',selected:null,pollMinutes:10};let cloudSnapshot=null,cloudPending=false;let route='dashboard',map=null,dashboardMap=null,markers=[],tileLayer=null,metric='temp',period='all',mapMode='satellite',compare=false,chartRange='7';
function load(){try{const s=JSON.parse(localStorage.getItem(STORE));if(s&&typeof s==='object')state={...state,...s};}catch{}state.events=state.events||[];state.stations=state.stations||[];state.readings=state.readings||{};if(!state.stations.length){state.stations=[{id:'estacao-01',name:'EcoSense · Sá Viana',lat:null,lon:null,endpoint:'',owner:'EcoSenseMonitor',created:new Date().toISOString()}];state.events.unshift({time:new Date().toISOString(),level:'info',title:'Primeiro acesso',description:'Estação de referência criada; informe coordenadas e fonte real de dados.',station:'estacao-01'});}if(!state.selected)state.selected=state.stations[0]?.id;save();}
function save(){let metadata={...state,readings:{},adminKey:state.adminKey||''};try{localStorage.setItem(STORE,JSON.stringify(metadata));}catch(err){console.warn('Falha ao salvar configurações',err)}}
const HISTORY_DB='ecosense_history_352';let historyDB=null;
function openHistoryDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window))return reject(Error('IndexedDB indisponível'));let request=indexedDB.open(HISTORY_DB,1);request.onupgradeneeded=()=>{let db=request.result;let st=db.createObjectStore('readings',{keyPath:['station','time']});st.createIndex('station','station',{unique:false})};request.onsuccess=()=>{historyDB=request.result;resolve(historyDB)};request.onerror=()=>reject(request.error)})}
function dbWriteReadings(records){if(!historyDB||!records.length)return Promise.resolve();return new Promise((resolve,reject)=>{let tx=historyDB.transaction('readings','readwrite'),store=tx.objectStore('readings');for(const record of records)store.put(record);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
function dbLoadReadings(){if(!historyDB)return Promise.resolve();return new Promise((resolve,reject)=>{let tx=historyDB.transaction('readings','readonly'),req=tx.objectStore('readings').getAll();req.onsuccess=()=>{let grouped={};for(let row of req.result){(grouped[row.station]??=[]).push(row)};state.readings=grouped;resolve()};req.onerror=()=>reject(req.error)})}
function showSyncProgress(msg){let node=document.querySelector('#historyProgress');if(!node){node=document.createElement('div');node.id='historyProgress';node.className='history-progress';document.body.appendChild(node)}node.textContent=msg;node.hidden=false}
function hideSyncProgress(){let e=document.querySelector('#historyProgress');if(e)e.hidden=true}

function log(title,description,level='info',station=''){state.events.unshift({time:new Date().toISOString(),title,description,level,station});state.events=state.events.slice(0,250);save();}
function toast(msg,error=false){let el=$('#toast');el.textContent=msg;el.className='toast'+(error?' error':'');clearTimeout(el.t);el.t=setTimeout(()=>el.classList.add('hidden'),4700)}
function current(){return state.stations.find(s=>s.id===state.selected)||state.stations[0]}
function rows(s=current()){return (state.readings[s?.id]||[]).slice().sort((a,b)=>new Date(a.time)-new Date(b.time))}
function latest(s){let r=state.readings[s.id];return r?.length?r.reduce((a,b)=>new Date(a.time)>new Date(b.time)?a:b):null}
function status(s){let r=latest(s);if(!r)return 'no-data';return Date.now()-Date.parse(r.time)<25*60*1000?'online':'offline'}
function filteredRows(s=current(),range=period){let a=rows(s);let duration={'1':3600000,'6':21600000,'24':86400000,'7':604800000,'30':2592000000,'all':Infinity}[range]??604800000;return duration===Infinity?a:a.filter(r=>Date.now()-Date.parse(r.time)<=duration)}
function numberOrNull(v){if(v==null||v==='')return null;let n=Number(String(v).trim().replace(',','.'));return Number.isFinite(n)?n:null}
function norm(src,station){if(!src||typeof src!=='object')return null;const obj=Object.fromEntries(Object.entries(src).map(([k,v])=>[k.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),v]));const pick=(...keys)=>{for(const key of keys)if(obj[key]!=null&&obj[key]!=='')return obj[key];return null};let t=pick('timestamp_utc','timestamp_recebimento','data_servidor','timestamp','data_hora','datetime','datahora','hora','time','data');let tm=t?new Date(t):null;if((!tm||Number.isNaN(tm.valueOf()))&&t&&/^\d{2}\/\d{2}\/\d{4}/.test(String(t))){let m=String(t).match(/(\d{2})\/(\d{2})\/(\d{4})(?:\s+(\d\d):(\d\d)(?::(\d\d))?)?/);tm=new Date(`${m[3]}-${m[2]}-${m[1]}T${m[4]||'00'}:${m[5]||'00'}:${m[6]||'00'}-03:00`)}if(!tm||Number.isNaN(tm.valueOf()))return null;const out={station:station||pick('estacao_id','station','id_estacao')||'estacao-01',time:tm.toISOString(),temp:numberOrNull(pick('temperatura_c','temperatura','temperature','temp','temperature_c')),humidity:numberOrNull(pick('umidade_relativa_perc','umidade_percent','umidade','humidity','umidade_relativa','ur')),pressure:numberOrNull(pick('pressao_atmosferica_hpa','pressao','pressure','pressao_hpa')),altitude:numberOrNull(pick('altitude_m','altitude')),rssi:numberOrNull(pick('rssi')),satellites:numberOrNull(pick('satellites','satelites')),battery:numberOrNull(pick('status_bateria_v','bateria_v','battery_v','tensao_bateria_v','bateria','battery','voltage')),latitude:numberOrNull(pick('latitude','lat')),longitude:numberOrNull(pick('longitude','lon','lng'))};return Object.values(out).slice(2).some(v=>v!=null)?out:null}
async function addRows(station,raw){let valid=raw.map(o=>norm(o,station)).filter(Boolean);if(!valid.length)return 0;let existing=state.readings[station]||[];let map=new Map(existing.map(r=>[r.time,r]));for(const row of valid)map.set(row.time,row);let next=[...map.values()].sort((a,b)=>a.time.localeCompare(b.time));state.readings[station]=next;
 let stationInfo=state.stations.find(s=>s.id===station);
 if(stationInfo&&(stationInfo.lat==null||stationInfo.lon==null)){
  let gps=[...valid].reverse().find(r=>r.latitude!=null&&r.longitude!=null&&Math.abs(r.latitude)<=90&&Math.abs(r.longitude)<=180);
  if(gps){stationInfo.lat=gps.latitude;stationInfo.lon=gps.longitude}
 }
 await dbWriteReadings(valid);save();return Math.max(0,next.length-existing.length)}
function parseCSV(text){let lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);if(lines.length<2)return[];let delim=(lines[0].match(/;/g)||[]).length>(lines[0].match(/,/g)||[]).length?';':',';function parseLine(line){let cells=[],acc='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quoted&&line[i+1]==='"'){acc+='"';i++}else quoted=!quoted}else if(c===delim&&!quoted){cells.push(acc);acc=''}else acc+=c}cells.push(acc);return cells}let headings=parseLine(lines[0]);return lines.slice(1).map(l=>Object.fromEntries(parseLine(l).map((v,i)=>[headings[i],v])))}
function getJSONrecords(j){if(Array.isArray(j))return j;for(let k of ['data','leituras','registros','readings','items','historico'])if(Array.isArray(j?.[k]))return j[k];return j&&typeof j==='object'?[j]:[]}
function download(name,text,mime){let blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),4000)}
function exportRows(format='csv',s=current()){let a=rows(s);if(!a.length)return toast('Sem medições para exportar.',true);if(format==='json'){download('ecosense_'+s.id+'.json',JSON.stringify(a,null,2),'application/json');return}let headers=['station','time','temp','humidity','pressure','altitude','rssi','satellites','battery'];let str='\uFEFF'+headers.join(';')+'\n'+a.map(r=>headers.map(k=>r[k]??'').join(';')).join('\n');download('ecosense_'+s.id+'.csv',str,'text/csv;charset=utf-8')}
async function backend(path,opts={}){if(!state.apiUrl)throw Error('Configure a API servidor central na aba Integrações antes de sincronizar dados compartilhados.');let url=state.apiUrl.replace(/\/$/,'')+path;let headers={'Content-Type':'application/json',...(opts.headers||{})};if(opts.method&&opts.method!=='GET'&&state.adminKey)headers['X-EcoSense-Admin-Key']=state.adminKey;let response=await fetch(url,{...opts,headers,cache:'no-store'});let j=await response.json().catch(()=>({}));if(!response.ok)throw Error(j.error||'Erro da API ('+response.status+')');return j}
async function syncOne(id){
 const station=state.stations.find(s=>s.id===id);if(!station)throw Error('Estação não encontrada');
 if(!state.apiUrl&&!station.endpoint)throw Error('Cadastre o endpoint Apps Script ou a API servidor central.');
 let offset=0,received=0,added=0,pages=0,total=null,lastPageFingerprint='';
 const pageSize=500;
 try{
  while(true){
   showSyncProgress('Importando histórico de '+station.name+': '+received.toLocaleString('pt-BR')+(total?' / '+total.toLocaleString('pt-BR'):'')+' registros');
   let raw;
   if(state.apiUrl){raw=await backend('/stations/'+encodeURIComponent(id)+'/readings?historico=true&offset='+offset+'&limit='+pageSize)}
   else{
    const url=station.endpoint+(station.endpoint.includes('?')?'&':'?')+'historico=true&offset='+offset+'&limit='+pageSize;
    try{const resp=await fetch(url,{redirect:'follow',cache:'no-store'});if(!resp.ok)throw Error('HTTP '+resp.status);raw=await resp.json()}
    catch(err){throw Error('Apps Script bloqueado pelo navegador (CORS/rede); configure a API servidor central. '+err.message)}
   }
   let chunk=getJSONrecords(raw);
   if(!Array.isArray(chunk))throw Error('Resposta de histórico inválida');
   const pageFingerprint=chunk.length?JSON.stringify([chunk[0],chunk[chunk.length-1]]):'';
   if(chunk.length&&pages>0&&pageFingerprint===lastPageFingerprint)throw Error('O servidor repetiu a mesma página de medições. Importação interrompida para evitar loop.');
   lastPageFingerprint=pageFingerprint;
   added+=await addRows(id,chunk);received+=chunk.length;pages++;
   if(pages%4===0){showSyncProgress('Importando histórico de '+station.name+': '+received.toLocaleString('pt-BR')+' recebidos · '+(state.readings[id]?.length||0).toLocaleString('pt-BR')+' disponíveis');if(route==='dashboard')refreshDashboardNumbers();await new Promise(resolve=>setTimeout(resolve,0));}
   if(Number.isFinite(Number(raw?.total))&&raw.total!=null)total=Number(raw.total);
   let hasMore=raw?.has_more===true||raw?.has_more==='true';
   let next=Number(raw?.next_offset);
   if(hasMore){if(!Number.isFinite(next)||next<=offset)next=offset+chunk.length}
   else if(raw?.has_more==null&&chunk.length===pageSize){hasMore=true;next=offset+chunk.length}
   if(!hasMore||!chunk.length)break;
   if(pages>=1000)throw Error('Limite de proteção atingido. Utilize o cache histórico da servidor central para volumes maiores.');
   offset=next;
  }
  log('Histórico integral sincronizado',`${received} registros recebidos; ${added} novos; ${pages} páginas.`, 'info',id);
  return added;
 }finally{hideSyncProgress()}
}


// O backend servidor central armazena o histórico integral. O navegador consome apenas
// o resumo e a amostragem da série temporal; cada visita evita reimportação maciça.
async function refreshCentralSnapshot(silent=false){
 if(!CENTRAL_API||cloudPending)return;
 cloudPending=true;
 try{
  const resp=await fetch(CENTRAL_API+'/snapshot',{cache:'no-store'});
  if(!resp.ok)throw Error('servidor central '+resp.status);
  const j=await resp.json();if(!j.ok)throw Error(j.error||'Resumo indisponível');
  cloudSnapshot=j;
  const id=j.station||'estacao-01';
  let st=state.stations.find(x=>x.id===id);
  if(!st){st={id,name:j.station_name||'EcoSense · Sá Viana',lat:null,lon:null,endpoint:'',owner:'EcoSenseMonitor'};state.stations.push(st)}
  // Amostra somente para os gráficos. As estatísticas globais vêm do backend.
  const sample=(j.sample||[]).map(r=>norm(r,id)).filter(Boolean);
  const latestRow=j.latest?norm(j.latest,id):null;
  if(latestRow&&!sample.some(x=>x.time===latestRow.time))sample.push(latestRow);
  // A base servidor central e autoritativa; nao misturar historico antigo do navegador com a amostra atual.
  state.readings[id]=sample.sort((a,b)=>a.time.localeCompare(b.time));
  if(j.latitude!=null&&j.longitude!=null){st.lat=Number(j.latitude);st.lon=Number(j.longitude)}
  state.apiUrl=CENTRAL_API;save();
  if(route==='dashboard')render();
  else if(route==='analises' || route==='estacoes')render();
  if(!silent&&j.complete===false)toast('Base servidor central em indexação inicial: '+Number(j.count||0).toLocaleString('pt-BR')+' registros já disponíveis.');
 }catch(err){if(!silent)toast('Conexão automática servidor central: '+err.message,true);console.warn('EcoSense servidor central snapshot',err)}
 finally{cloudPending=false}
}
function cachedStats(metricName){if(!cloudSnapshot||!cloudSnapshot.stats)return null;return cloudSnapshot.stats[metricName]||null}
function centralTotal(){return cloudSnapshot?.count??null}

function refreshDashboardNumbers(){
 if(route!=='dashboard')return;
 const total=Object.values(state.readings).reduce((n,a)=>n+a.length,0);
 const cards=document.querySelectorAll('.kpi-grid.six .kpi-value');
 if(cards[5])cards[5].textContent=total.toLocaleString('pt-BR');
 const currentStation=current(),recent=currentStation?latest(currentStation):null;
 for(const [i,k,u] of [[0,'temp',' °C'],[1,'humidity',' %'],[2,'pressure',' hPa'],[3,'altitude',' m'],[4,'battery',' V']])if(cards[i])cards[i].textContent=unit(recent?.[k],u);
 // Other historical panels refresh at completion without recreating map on every page.
}
async function syncAll(){let success=0,failed=[];for(let s of state.stations){if(!(s.endpoint||state.apiUrl))continue;try{await syncOne(s.id);success++}catch(e){failed.push(s.name+': '+e.message);log('Falha de sincronização',e.message,'aviso',s.id)}}render();toast(failed.length?`${success} estações sincronizadas; ${failed.length} falharam. Consulte os logs.`:`Sincronização concluída: ${success} estação(ões).`,!!failed.length)}
function svgChart(data,keys=['temp'],colors=['#ffae23'],height=215){if(data.length>900){let step=Math.ceil(data.length/900);data=data.filter((_,i)=>i%step===0||i===data.length-1)}const width=760,m={top:19,right:16,bottom:30,left:46},plotW=width-m.left-m.right,plotH=height-m.top-m.bottom;let times=data.map(r=>Date.parse(r.time));let values=data.flatMap(r=>keys.map(k=>r[k]).filter(x=>x!=null));if(!values.length)return `<div class="empty"><strong>Sem medições disponíveis</strong>Importe dados ou conecte sua estação para visualizar séries temporais.</div>`;let min=Math.min(...values),max=Math.max(...values),pad=Math.max((max-min)*.17,1);min-=pad;max+=pad;let tx=x=>m.left+(x-times[0])/(Math.max(times[times.length-1]-times[0],1))*plotW,ty=y=>m.top+(max-y)/(max-min)*plotH;let grid=[0,1,2,3,4].map(i=>`<line x1="${m.left}" x2="${width-m.right}" y1="${m.top+i*plotH/4}" y2="${m.top+i*plotH/4}" stroke="#6eafa44c"/><text x="${m.left-8}" y="${m.top+i*plotH/4+4}" text-anchor="end">${unit(max-i*(max-min)/4,'',1)}</text>`).join('');let paths=keys.map((k,i)=>{let points=data.filter(r=>r[k]!=null).map(r=>[tx(Date.parse(r.time)),ty(r[k])]);if(!points.length)return'';let d=points.map(([x,y],j)=>(j?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)).join(' ');let fill=d+` L${points[points.length-1][0].toFixed(1)} ${m.top+plotH} L${points[0][0].toFixed(1)} ${m.top+plotH} Z`;return `<path d="${fill}" fill="${colors[i]}" opacity=".12"/><path d="${d}" fill="none" stroke="${colors[i]}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`}).join('');let span=Math.abs(times[times.length-1]-times[0]);let ticks=Array.from({length:5},(_,i)=>{let t=new Date(times[0]+(times[times.length-1]-times[0])*i/4);let opts=span<86400000?{hour:'2-digit',minute:'2-digit'}:span<14*86400000?{day:'2-digit',month:'2-digit',hour:'2-digit'}:{day:'2-digit',month:'2-digit',year:'2-digit'};let label=t.toLocaleString('pt-BR',{timeZone:'America/Fortaleza',...opts});return `<text x="${(m.left+i*plotW/4).toFixed(1)}" y="${height-7}" text-anchor="middle">${label}</text>`}).join('');return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Gráfico de série temporal">${grid}${paths}${ticks}</svg>`}
function kpi(name,value,subtitle,icon,cls=''){return `<div class="card glass ${cls}"><div class="kpi-title"><span class="kpi-symbol">${icon}</span>${name}</div><div class="kpi-value">${value}</div><div class="kpi-sub">${subtitle}</div></div>`}
function panel(title,desc,body,extra=''){return `<section class="card glass"><div class="panel-heading"><div><h2>${title}</h2><p>${desc}</p></div>${extra}</div>${body}</section>`}
function empty(t='Ainda não há dados',p='Conecte uma estação ou importe uma série temporal para começar.') {return `<div class="empty"><strong>${t}</strong>${p}</div>`}
function dashboard(){
 const station=current(),last=station?latest(station):null;
 const total=centralTotal()??Object.values(state.readings).reduce((a,b)=>a+b.length,0),online=state.stations.filter(s=>status(s)==='online').length;
 const all=state.stations.flatMap(s=>state.readings[s.id]||[]);
 const observed=all.map(r=>r.time).sort(),first=cloudSnapshot?.first_time||observed[0],lastTime=cloudSnapshot?.last_time||observed.at(-1);
 const data=filteredRows(station,'all');
 const temperatures=data.map(r=>r.temp).filter(v=>v!=null);
 const centralTemp=cachedStats('temp');const average=centralTemp?.avg??(temperatures.length?temperatures.reduce((a,b)=>a+b,0)/temperatures.length:null);
 return `<div class="grid kpi-grid six">${kpi('Temperatura',unit(last?.temp,' °C'),'Última medição da estação','♨','orange')}${kpi('Umidade relativa',unit(last?.humidity,' %'),'Última medição da estação','◉','blue')}${kpi('Pressão atmosférica',unit(last?.pressure,' hPa'),'Última medição da estação','◷','green')}${kpi('Altitude',unit(last?.altitude,' m'),'Quando informada pelo GPS','⌖')}${kpi('Tensão da bateria',unit(last?.battery,' V'),'Se o hardware enviar essa medida','ϟ','green')}${kpi('Registros históricos',total.toLocaleString('pt-BR'),cloudSnapshot?'Histórico no servidor servidor central':'Registros disponíveis neste navegador','▤','blue')}</div>
 <div class="grid section-grid">${panel('⌖ Visão geográfica','Mapa real, localização e status operacional.',`<div class="map-preview" id="dashboardRealMap"></div><div class="legend" style="margin-top:14px"><span><i class="bullet"></i> Online ${online}</span><span><i class="bullet orange"></i> Sem transmissão recente ${state.stations.length-online}</span><span>${state.stations.length} estações</span></div>`,`<button class="small-btn btn-orange" data-go="mapa">Abrir mapa ›</button>`)}${panel('☷ Cobertura histórica','Período completo disponível na base.',`<div class="stat-list"><span>Primeira leitura</span><strong>${dateFmt(first)}</strong><span>Última leitura</span><strong>${dateFmt(lastTime)}</strong><span>Temperatura média (histórico)</span><strong>${unit(average,' °C')}</strong><span>Mínima</span><strong>${unit(centralTemp?.min??(temperatures.length?temperatures.reduce((a,b)=>Math.min(a,b),Infinity):null),' °C')}</strong><span>Máxima</span><strong>${unit(centralTemp?.max??(temperatures.length?temperatures.reduce((a,b)=>Math.max(a,b),-Infinity):null),' °C')}</strong><span>Estações online agora</span><strong>${online} / ${state.stations.length}</strong></div>`)}</div>
 <div class="grid section-grid second">${panel('⌁ Série histórica completa — Temperatura',cloudSnapshot?'Amostra visual do histórico integral processado na servidor central.':'Todo o intervalo registrado no Google Apps Script e importações.',`<div class="chart-wrap">${svgChart(data,['temp'],['#42e99b'])}</div>`,`<button class="small-btn" data-go="analises">Ver análises ›</button>`)}${panel('▤ Variáveis disponíveis','Medições reais da estação selecionada.',`<div class="stat-list"><span>Temperatura</span><strong>${(cachedStats('temp')?.count??data.filter(r=>r.temp!=null).length).toLocaleString('pt-BR')}</strong><span>Umidade</span><strong>${(cachedStats('humidity')?.count??data.filter(r=>r.humidity!=null).length).toLocaleString('pt-BR')}</strong><span>Pressão</span><strong>${(cachedStats('pressure')?.count??data.filter(r=>r.pressure!=null).length).toLocaleString('pt-BR')}</strong><span>Bateria</span><strong>${(cachedStats('battery')?.count??data.filter(r=>r.battery!=null).length).toLocaleString('pt-BR')}</strong></div>`)}</div>`
}
function mapSidebar(){let selection=state.stations.filter(s=>!$('#mapSearch')?.value||`${s.name} ${s.id}`.toLowerCase().includes($('#mapSearch').value.toLowerCase()));return `<div class="card glass map-sidebar"><div class="panel-heading"><div><h2>◉ Mapa de estações</h2><p>Estações cadastradas</p></div></div><input class="search" id="mapSearch" placeholder="Buscar estação ou ID..."><div class="legend" style="margin-top:13px"><span><i class="bullet"></i> Online: ${state.stations.filter(s=>status(s)==='online').length}</span><span><i class="bullet gray"></i> Sem dados: ${state.stations.filter(s=>status(s)!=='online').length}</span></div><div class="divider"></div><div id="mapStations">${selection.map(s=>`<div class="station-card ${s.id===state.selected?'selected':''}" data-focus="${html(s.id)}"><strong>${html(s.name)}</strong><small>${html(s.id)} · ${status(s)==='online'?'Online':status(s)==='offline'?'Dados antigos':'Aguardando dados'}</small><br><small>${s.lat!=null&&s.lon!=null?`${unit(s.lat,'',5)}, ${unit(s.lon,'',5)}`:'Coordenadas não definidas'}</small></div>`).join('')}</div><button class="btn" data-add-station="1" style="width:100%;margin-top:10px">+ Nova estação</button></div>`}
function toolsMap(){return `<div class="card glass map-tools"><div class="panel-heading"><div><h2>⚒ Ferramentas do mapa</h2><p>Cartografia e dados geográficos</p></div></div><div class="stack"><label class="field">Cartografia<select id="mapLayer"><option value="satellite" ${mapMode==='satellite'?'selected':''}>Satélite — Esri</option><option value="streets" ${mapMode==='streets'?'selected':''}>OpenStreetMap</option><option value="topo" ${mapMode==='topo'?'selected':''}>Topográfico — Esri</option></select></label><label class="field">Ir para coordenadas<input id="gotoCoords" placeholder="-2.5557, -44.3009"></label><button class="btn-secondary" id="coordsGo">⌖ Centralizar mapa</button><button class="btn-secondary" id="mapFit">⊞ Enquadrar estações</button><button class="btn-secondary" id="mapMeasure">⌁ Medir distância</button><div class="divider"></div><button class="btn-secondary" id="geoExport">↓ Exportar GeoJSON</button><button class="btn-secondary" id="geoImport">↑ Importar GeoJSON</button><input hidden type="file" id="geoFile" accept=".geojson,.json"><div class="divider"></div><div class="legend"><span><i class="bullet"></i> Dados recentes</span><span><i class="bullet orange"></i> Antigos</span><span><i class="bullet gray"></i> Sem dados</span></div><small style="color:var(--muted)">A posição no mapa usa somente coordenadas cadastradas. Não há estações ou medições simuladas.</small></div></div>`}
function mapaPage(){return `<div class="full-map-layout" id="mapLayout">${mapSidebar()}<div class="map-main"><div id="mapCanvas"></div><div class="map-overlay">Mapa interativo · ${state.stations.filter(s=>s.lat!=null&&s.lon!=null).length} estação(ões) georreferenciadas · posição fixa por estação</div><div class="map-live-meta" id="mapLiveMeta">Atualização conforme última telemetria recebida</div><button class="map-fullscreen-btn" id="mapFullscreen" title="Expandir mapa">⛶ Tela cheia</button></div>${toolsMap()}</div>`}
function initMap(){if(!window.L){$('#mapCanvas').innerHTML=empty('Mapa indisponível','A biblioteca Leaflet não carregou. Verifique sua conexão à internet.');return}if(map){map.remove();map=null;tileLayer=null;markers=[]}map=L.map('mapCanvas',{zoomControl:false}).setView([-2.5557,-44.3009],11);L.control.zoom({position:'bottomright'}).addTo(map);renderTiles();drawMarkers();requestAnimationFrame(()=>requestAnimationFrame(()=>map?.invalidateSize({pan:false})));[200,550,1200].forEach(ms=>setTimeout(()=>{if(map&&route==='mapa')map.invalidateSize({pan:false})},ms));if(window.ResizeObserver){window.__ecoMapResize?.disconnect();window.__ecoMapResize=new ResizeObserver(()=>{if(map&&route==='mapa')map.invalidateSize({pan:false})});window.__ecoMapResize.observe(document.getElementById('mapCanvas'))}}
const OSM_TILES='https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';
const ESRI_SAT='https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}';
const ESRI_TOPO='https://server.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}';
function makeTiles(target,kind,preview=false){
 const satellite=kind==='satellite',openStreet=kind==='streets';
 const url=openStreet?OSM_TILES:kind==='topo'?ESRI_TOPO:ESRI_SAT;
 const lyr=L.tileLayer(url,{maxZoom:19,maxNativeZoom:18,keepBuffer:4,updateWhenIdle:true,
  attribution:openStreet?'© OpenStreetMap contributors':'Tiles © Esri',crossOrigin:false});
 let errors=0,loaded=0,recovered=false;
 lyr.on('tileload',()=>{loaded++;});
 lyr.on('tileerror',()=>{
  errors++;
  // Switch to a publicly accessible street basemap rather than leaving missing blocks.
  if(!openStreet && errors>=3 && !recovered){
   recovered=true;
   if(!preview){mapMode='streets';let select=document.querySelector('#mapLayer');if(select)select.value='streets';}
   target.removeLayer(lyr);
   L.tileLayer(OSM_TILES,{maxZoom:19,keepBuffer:4,attribution:'© OpenStreetMap contributors'}).on('tileerror',()=>{
    if(!preview)showMapWarning('A cartografia não carregou. Verifique o acesso aos servidores de mapas.');
   }).addTo(target);
   if(!preview){toast('Satélite indisponível: mapa alternado para OpenStreetMap.');showMapWarning('Mapa alternado para OpenStreetMap devido a falha no satélite.');}
   else showMiniWarning('Imagens de satélite indisponíveis: exibindo mapa de ruas.');
  }
 });
 return lyr.addTo(target)
}
function showMapWarning(message){let mapEl=document.querySelector('.map-main');if(!mapEl)return;let warn=document.querySelector('#mapWarning');if(!warn){warn=document.createElement('div');warn.id='mapWarning';warn.className='map-warning';mapEl.appendChild(warn);}warn.textContent=message}
function showMiniWarning(message){let el=document.querySelector('#dashboardRealMap');if(!el)return;let note=document.createElement('div');note.className='map-warning mini';note.textContent=message;el.append(note)}
function renderTiles(){if(!map)return;if(tileLayer)map.removeLayer(tileLayer);tileLayer=makeTiles(map,mapMode)}
function initDashboardMap(){
 let el=document.querySelector('#dashboardRealMap');if(!el||!window.L)return;
 if(dashboardMap){try{dashboardMap.remove()}catch{} dashboardMap=null}
 const mini=L.map(el,{zoomControl:false,dragging:false,scrollWheelZoom:false,doubleClickZoom:false,attributionControl:false}).setView([-2.55,-44.31],11);
 dashboardMap=mini;
 makeTiles(mini,'satellite',true);
 const points=[];
 for(let s of state.stations){if(s.lat==null||s.lon==null)continue;points.push([+s.lat,+s.lon]);L.circleMarker([+s.lat,+s.lon],{radius:7,color:'#dcfff1',fillColor:status(s)==='online'?'#31f8a0':'#f4a943',weight:2,fillOpacity:1}).addTo(mini).bindTooltip(s.name)}
 if(points.length===1)mini.setView(points[0],12);
 else if(points.length>1)mini.fitBounds(points,{padding:[20,20],maxZoom:13});
 requestAnimationFrame(()=>mini.invalidateSize({pan:false}));[200,900].forEach(ms=>setTimeout(()=>{if(dashboardMap===mini&&document.contains(el))mini.invalidateSize({pan:false})},ms));
}
function drawMarkers(){if(!map)return;for(let m of markers)map.removeLayer(m);markers=[];for(let s of state.stations){if(!Number.isFinite(+s.lat)||!Number.isFinite(+s.lon)||s.lat==null||s.lon==null)continue;let cls=status(s)==='online'?'':' '+(status(s)==='offline'?'warning':'stale');let icon=L.divIcon({html:`<div class="map-pin${cls}"><span>●</span></div>`,className:'',iconSize:[26,26],iconAnchor:[13,24]});let r=latest(s);let marker=L.marker([+s.lat,+s.lon],{icon}).addTo(map).bindPopup(`<b>${html(s.name)}</b><br>${html(s.id)}<br>${r?`Temperatura: ${unit(r.temp,' °C')}<br>Umidade: ${unit(r.humidity,' %')}<br>Pressão: ${unit(r.pressure,' hPa')}<br>${dateFmt(r.time)}`:'Nenhuma medição importada'}`);marker.on('click',()=>{state.selected=s.id;save()});markers.push(marker)}}
function analysisPage(){let s=current(),r=filteredRows(s),vals=r.map(x=>x[metric]).filter(x=>x!=null),mean=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null,vmin=vals.length?vals.reduce((a,b)=>Math.min(a,b),Infinity):null,vmax=vals.length?vals.reduce((a,b)=>Math.max(a,b),-Infinity):null,dev=vals.length?Math.sqrt(vals.reduce((a,b)=>a+(b-mean)**2,0)/vals.length):null;if(period==='all'&&cloudSnapshot&&s?.id===cloudSnapshot.station){let agg=cachedStats(metric);if(agg){mean=agg.avg;vmin=agg.min;vmax=agg.max;dev=agg.stddev}}let titles={temp:'Temperatura (°C)',humidity:'Umidade relativa (%)',pressure:'Pressão (hPa)',altitude:'Altitude (m)',battery:'Bateria (V)',rssi:'Sinal Wi-Fi (dBm)',satellites:'Satélites GPS'};let colors={temp:'#ffae23',humidity:'#27e0e7',pressure:'#48ef87',altitude:'#d9fb78',battery:'#b8a5ff',rssi:'#83aafa',satellites:'#93ecdb'};let stationOpts=state.stations.map(x=>`<option value="${html(x.id)}" ${x.id===state.selected?'selected':''}>${html(x.name)}</option>`).join('');let grouped=state.stations.map(x=>({name:x.name,vals:filteredRows(x).map(v=>v[metric]).filter(v=>v!=null)}));let bars=grouped.filter(x=>x.vals.length).slice(0,7);let max=bars.reduce((max,x)=>Math.max(max,x.vals.reduce((a,b)=>a+b,0)/x.vals.length),1);let hist=Array.from({length:84},(_,i)=>{let a=rows(s),hour=i%12*2,day=Math.floor(i/12);let ref=new Date(Date.now()-(6-day)*86400000),v=a.filter(x=>{let t=new Date(x.time);return t.toDateString()===ref.toDateString()&&t.getHours()>=hour&&t.getHours()<hour+2&&x.temp!=null});return v.length?v.reduce((x,y)=>x+y.temp,0)/v.length:null});return `<div class="card glass toolbar"><label class="field">Período<select id="analysisPeriod"><option value="24" ${period==='24'?'selected':''}>Últimas 24h</option><option value="7" ${period==='7'?'selected':''}>Últimos 7 dias</option><option value="30" ${period==='30'?'selected':''}>Últimos 30 dias</option><option value="all" ${period==='all'?'selected':''}>Todo o histórico</option></select></label><label class="field">Estação<select id="analysisStation">${stationOpts}</select></label><label class="field">Variável<select id="analysisMetric">${Object.entries(titles).map(([k,v])=>`<option value="${k}" ${metric===k?'selected':''}>${v}</option>`).join('')}</select></label><button id="expCSV" class="btn">↓ Exportar CSV</button><button id="expJSON" class="btn-secondary">↓ JSON</button></div><div class="grid section-grid">${panel('⌁ Série temporal — '+titles[metric],'Evolução registrada da variável no período selecionado.',`<div class="chart-wrap" style="height:280px">${svgChart(r,[metric],[colors[metric]],280)}</div>`)}${panel('▥ Comparativo entre estações','Média dos registros disponíveis por estação.',bars.length?`<div class="stack">${bars.map(x=>{let avg=x.vals.reduce((a,b)=>a+b,0)/x.vals.length;return `<div><div style="display:flex;justify-content:space-between;font-size:11px;gap:10px"><span>${html(x.name)}</span><b>${unit(avg)}</b></div><div style="height:12px;border-radius:7px;background:#183e38;overflow:hidden;margin-top:6px"><div style="width:${Math.min(100,avg/max*100)}%;background:linear-gradient(90deg,#048a66,#71f66e);height:100%;border-radius:7px"></div></div></div>`}).join('')}</div>`:empty('Sem comparação disponível','Importe medições em pelo menos uma estação.'))}</div><div class="grid" style="grid-template-columns:1.35fr 1fr 1fr;margin-top:16px">${panel('▦ Padrão horário — Temperatura','Média por intervalo de 2 horas nos últimos sete dias.',`<div class="heatmap">${hist.map(v=>`<div class="cell" title="${v==null?'Sem dados':unit(v,' °C')}" style="background:${v==null?'#173a38':`hsl(${Math.max(4,Math.min(170,170-(v-18)*11))} 82% 47%)`}"></div>`).join('')}</div><div class="heat-legend"><span>00h</span><span>06h</span><span>12h</span><span>18h</span><span>22h</span></div>`)}${panel('◈ Insights sobre o período','Indicadores calculados dos registros selecionados.',r.length?`<div class="stack"><div class="event"><span class="event-icon">Σ</span><div><strong>${period==='all'&&cloudSnapshot&&s?.id===cloudSnapshot.station?(cachedStats(metric)?.count??vals.length):vals.length} observações válidas</strong><small>Variável: ${titles[metric]}</small></div></div><div class="event"><span class="event-icon">↗</span><div><strong>Amplitude: ${unit(vmax-vmin)}</strong><small>Máximo menos mínimo</small></div></div><div class="event"><span class="event-icon">⌁</span><div><strong>Período: ${html(period==='all'?'todo o histórico':period==='24'?'24 horas':period+' dias')}</strong><small>Estatísticas descritivas, sem previsão artificial</small></div></div></div>`:empty('Sem insights estatísticos'))}${panel('▤ Resumo estatístico','Valores calculados sem dados demonstrativos.',`<div class="stat-list"><span>Média</span><strong>${unit(mean)}</strong><span>Desvio padrão</span><strong>${unit(dev)}</strong><span>Máximo</span><strong>${unit(vmax)}</strong><span>Mínimo</span><strong>${unit(vmin)}</strong><span>N de registros</span><strong>${(period==='all'&&cloudSnapshot&&s?.id===cloudSnapshot.station)?(cachedStats(metric)?.count??vals.length):vals.length}</strong></div>`)}</div>`}
function stationTable(){return `<div class="card glass">${panelHeading('Estações cadastradas','Cadastre coordenadas e endpoints reais.')}<div class="table-wrap"><table><thead><tr><th>Estação</th><th>ID</th><th>Latitude / longitude</th><th>Última leitura</th><th>Status</th><th>Ações</th></tr></thead><tbody>${state.stations.map(s=>{let r=latest(s);return `<tr><td><b>${html(s.name)}</b></td><td>${html(s.id)}</td><td>${s.lat!=null&&s.lon!=null?`${unit(s.lat,'',5)}, ${unit(s.lon,'',5)}`:'Não informado'}</td><td>${dateFmt(r?.time)}</td><td><span class="badge ${status(s)==='online'?'':status(s)==='offline'?'offline':'no-data'}">${status(s)==='online'?'Online':status(s)==='offline'?'Histórico':'Sem dados'}</span></td><td><div class="actions"><button data-edit="${html(s.id)}">Editar</button><button data-focus="${html(s.id)}">Mapa</button><button data-delete="${html(s.id)}">Excluir</button></div></td></tr>`}).join('')}</tbody></table></div></div>`}
function panelHeading(title,description){return `<div class="panel-heading"><div><h2>${title}</h2><p>${description}</p></div></div>`}
function stationPage(){return `${stationTable()}<div style="margin-top:16px" class="grid section-grid">${panel('Importar leituras de estações','CSV/JSON com timestamp e ao menos uma variável atmosférica.',`<div class="form-row"><label class="field">Estação<select id="importStation">${state.stations.map(s=>`<option value="${html(s.id)}">${html(s.name)}</option>`).join('')}</select></label><label class="field">Arquivo<input type="file" id="importFile" accept=".csv,.json"></label><button class="btn" id="importReadings">Importar medições</button></div>`)}${panel('Integridade dos dados','Os dados importados não são fictícios.',`<p style="color:var(--muted);font-size:12px">As leituras são organizadas por estação e timestamp, deduplicadas e armazenadas neste navegador. Para compartilhar entre usuários, implante e configure a API central servidor central.</p><button class="btn-secondary" id="backupJSON">↓ Backup completo deste navegador</button>`)}</div>`}
function logsPage(){return `${panel('☷ Eventos do sistema','Registro local das ações realizadas na versão web.',`<div class="form-row" style="margin-bottom:12px"><label class="field">Filtrar tipo<select id="logLevel"><option value="all">Todos</option><option value="info">Informações</option><option value="aviso">Avisos</option><option value="critico">Críticos</option></select></label><button class="btn-secondary" id="downloadLogs">↓ Exportar eventos</button></div><div id="logOutput">${renderLogs('all')}</div>`)}`}
function renderLogs(level){let events=state.events.filter(e=>level==='all'||e.level===level);return events.length?`<div class="table-wrap"><table><thead><tr><th>Data/hora</th><th>Tipo</th><th>Evento</th><th>Estação</th><th>Detalhes</th></tr></thead><tbody>${events.map(e=>`<tr><td>${dateFmt(e.time)}</td><td>${html(e.level)}</td><td>${html(e.title)}</td><td>${html(e.station||'—')}</td><td>${html(e.description)}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum evento para este filtro')}
function integrationPage(){return `<div class="info-flag"><strong>Integração real, sem dados fictícios.</strong> O Apps Script pode bloquear acesso direto do navegador por CORS. A API servidor central opcional atua como intermediária para sincronizar medições e disponibilizar leituras compartilhadas. Nenhum login ou segredo servidor central deve ser colocado neste HTML.</div><div class="grid section-grid">${panel('◇ API central servidor central','Conexão HTTP com a API instalada na sua própria conta servidor central.',`<div class="stack"><label class="field">URL da API (Function URL ou API Gateway)<input id="apiUrl" type="url" placeholder="https://xxxx.lambda-url.us-east-2.on.aws" value="${html(state.apiUrl)}"></label><label class="field">Chave administrativa (armazenada somente neste navegador)<input id="adminKey" type="password" placeholder="Necessária apenas para operações protegidas" value="${html(state.adminKey)}"></label><div class="form-row"><button id="saveApi" class="btn">Salvar conexão</button><button id="testApi" class="btn-secondary">Testar API</button></div><small style="color:var(--muted)">A chave concede acesso administrativo: utilize somente em dispositivo confiável. Para uso público, configure autenticação de usuários na servidor central.</small></div>`)}${panel('◉ Google Apps Script','Endpoints das estações; sincronização de dados disponíveis.',`<div class="stack"><label class="field">Estação<select id="syncStation">${state.stations.map(s=>`<option value="${html(s.id)}">${html(s.name)}</option>`).join('')}</select></label><label class="field">Endpoint cadastrado<input value="${html(current()?.endpoint||'Não cadastrado')}" readonly></label><button id="syncSelected" class="btn">⟳ Sincronizar estação</button><button id="syncEveryone" class="btn-secondary">⟳ Sincronizar todas</button><button id="loadStationsservidor central" class="btn-secondary">↓ Carregar estações da servidor central</button><button class="btn-secondary" data-go="estacoes">Gerenciar estações</button></div>`)}</div><div class="grid section-grid" style="margin-top:16px">${panel('☁ Dados meteorológicos de referência','Open-Meteo — dados externos independentes das suas estações.',`<div class="stack"><p style="color:var(--muted);font-size:12px">Consulta externa disponível para coordenadas de estação cadastrada. Esses valores não substituem os sensores EcoSense.</p><button id="fetchMeteo" class="btn-secondary">Consultar meteorologia externa</button><div id="meteoResult"></div></div>`)}${panel('⇩ Intercâmbio de dados','Exportação e portabilidade dos registros.',`<div class="form-row"><button id="exportCSV" class="btn-secondary">Exportar CSV</button><button id="exportJSON" class="btn-secondary">Exportar JSON</button><button id="backupAll" class="btn-secondary">Backup completo</button></div>`)}</div>`}
function updatesPage(){return `<div class="card glass green update-hero"><div><div class="kpi-title"><img src="../assets/logo.png" style="height:52px;float:left;margin-right:15px"> EcoSenseMonitor Web</div><div class="version">v3.5 Web</div><small>Aplicativo executado diretamente no navegador</small></div><div><span class="chip">Canal web estável</span><p style="font-size:12px">Versão publicada pelo GitHub Pages</p></div><div><strong style="font-size:23px;color:var(--lime)">✓ Sem instalador</strong><p>Atualize a página após nova implantação.</p></div></div><div class="grid section-grid" style="margin-top:16px">${panel('⟳ Como funcionam as atualizações','A distribuição web difere da atualização do aplicativo Windows.',`<div class="stack"><div class="event"><div class="event-icon">1</div><div><strong>Publicação no Amplify</strong><small>O proprietário envia uma nova versão da aplicação.</small></div></div><div class="event"><div class="event-icon">2</div><div><strong>Atualização dos arquivos</strong><small>Os navegadores passam a buscar os arquivos do novo deploy.</small></div></div><div class="event"><div class="event-icon">3</div><div><strong>Recarregamento seguro</strong><small>Os dados locais são preservados no mesmo domínio/navegador.</small></div></div></div>`)}${panel('⚙ Estado da versão','Publicação e manutenção.',`<div class="stat-list"><span>Plataforma</span><strong>Web</strong><span>Versão</span><strong>3.5</strong><span>Hospedagem</span><strong>GitHub Pages</strong><span>Manifesto Windows</span><strong>Independente</strong></div><button class="btn" style="margin-top:17px" id="reloadApp">⟳ Recarregar aplicativo</button>`)}</div>`}
function settingsPage(){return `<div class="grid section-grid">${panel('⚙ Preferências','Configurações locais desta instalação web.',`<div class="stack"><label class="field">Intervalo de sincronização automática<select id="pollTime">${[0,5,10,15,30,60].map(x=>`<option value="${x}" ${Number(state.pollMinutes)===x?'selected':''}>${x===0?'Desativado':x+' minutos'}</option>`).join('')}</select></label><label class="switch-row"><span>Usar tema claro</span><input type="checkbox" id="lightSwitch" ${state.theme==='light'?'checked':''}></label><button class="btn" id="settingsSave">Salvar preferências</button></div>`)}${panel('▤ Armazenamento local','Dados presentes neste navegador.',`<div class="stat-list"><span>Estações</span><strong>${state.stations.length}</strong><span>Medições</span><strong>${Object.values(state.readings).reduce((a,r)=>a+r.length,0)}</strong><span>Eventos</span><strong>${state.events.length}</strong></div><button id="backupBtn" class="btn-secondary" style="margin-top:14px">↓ Exportar backup</button><p style="color:var(--muted);font-size:11px">A exclusão de dados deste navegador pode apagar o histórico local. Faça backup antes.</p>`)}</div>`}
const pages={dashboard:['Bem-vindo ao EcoSenseMonitor','Monitoramento ambiental inteligente, em tempo real.',dashboard],mapa:['Mapa de estações','Localização, dados atmosféricos e ferramentas geográficas.',mapaPage],analises:['Central de análises','Exploração científica das medições, comparações e estatísticas.',analysisPage],estacoes:['Gerenciamento de estações','Cadastre, organize e monitore sua rede atmosférica.',stationPage],logs:['Logs do sistema','Histórico de sincronizações, importações e diagnósticos.',logsPage],integracoes:['Integrações e dados','servidor central, Google Apps Script e meteorologia de referência.',integrationPage],atualizacoes:['Central de atualizações','A interface web recebe melhorias por novas publicações no GitHub Pages.',updatesPage],configuracoes:['Configurações','Preferências, armazenamento e sincronização automática.',settingsPage]};
function render(){if(dashboardMap){try{dashboardMap.remove()}catch{}dashboardMap=null}let p=pages[route];$('#pageTitle').textContent=p[0];$('#pageSubtitle').textContent=p[1];$('#pageAction').innerHTML=route==='estacoes'?'<button class="btn btn-orange" data-add-station="1">+ Adicionar estação</button>':route==='dashboard'?'<button class="small-btn btn-orange" data-go="mapa">Abrir mapa ›</button>':'';$('#pageContent').innerHTML=p[2]();$$('#nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===route));let any=state.stations.some(s=>status(s)==='online');$('#statusText').textContent=cloudSnapshot?'Base servidor central: '+Number(cloudSnapshot.count||0).toLocaleString('pt-BR')+' registros':any?'Estações online':'Aguardando dados';$('#statusDot').classList.toggle('live',!!cloudSnapshot||any);if(route==='mapa')initMap();if(route==='dashboard')initDashboardMap();if(route==='integracoes')$('#apiUrl').value=state.apiUrl;}
function navigate(page){if(!pages[page])return; if(map && route==='mapa'){try{map.remove()}catch{} map=null;tileLayer=null;}route=page;$('#content').scrollTop=0;$('.sidebar').classList.remove('show');render()}
function stationModal(s=null){let isEdit=!!s,modal=document.createElement('div');modal.className='modal-backdrop';modal.id='stationDialog';modal.innerHTML=`<div class="modal"><h2>${isEdit?'Editar estação':'Cadastrar estação'}</h2><form id="stationForm"><div class="stack"><label class="field">Identificador único<input name="id" required maxlength="100" value="${html(s?.id||'')}" ${isEdit?'readonly':''} placeholder="estacao-02"></label><label class="field">Nome da estação<input name="name" required maxlength="150" value="${html(s?.name||'')}" placeholder="EcoSense · Jardim Tropical"></label><div class="form-row"><label class="field">Latitude<input type="number" name="lat" step="any" min="-90" max="90" value="${s?.lat??''}" placeholder="-2.5557"></label><label class="field">Longitude<input type="number" name="lon" step="any" min="-180" max="180" value="${s?.lon??''}" placeholder="-44.3009"></label></div><label class="field">Endpoint Google Apps Script (HTTPS)<input type="url" name="endpoint" value="${html(s?.endpoint||'')}" placeholder="https://script.google.com/macros/s/.../exec"></label><label class="field">Responsável<input name="owner" value="${html(s?.owner||'')}"></label></div><div class="modal-actions"><button class="btn-secondary" type="button" id="cancelStation">Cancelar</button><button class="btn" type="submit">Salvar estação</button></div></form></div>`;document.body.append(modal);$('#cancelStation').onclick=()=>modal.remove();modal.onclick=e=>{if(e.target===modal)modal.remove()};$('#stationForm').onsubmit=async e=>{e.preventDefault();let f=e.target;const id=f.elements.id.value.trim(),name=f.elements.name.value.trim(),endpoint=f.elements.endpoint.value.trim(),lat=f.elements.lat.value===''?null:Number(f.elements.lat.value),lon=f.elements.lon.value===''?null:Number(f.elements.lon.value);if(!/^[a-zA-Z0-9_-]{2,100}$/.test(id))return toast('ID: 2 a 100 letras, números, _ ou -.',true);if(!isEdit&&state.stations.some(s=>s.id===id))return toast('Esse ID já existe.',true);if(endpoint&&!endpoint.startsWith('https://'))return toast('Utilize endpoint HTTPS.',true);let data={id,name,lat,lon,endpoint,owner:f.elements.owner.value.trim(),created:s?.created||new Date().toISOString()};if(isEdit)state.stations=state.stations.map(st=>st.id===id?data:st);else state.stations.push(data);state.selected=id;save();log(isEdit?'Estação editada':'Estação cadastrada',name,'info',id);modal.remove();render();if(state.apiUrl){try{await backend('/stations',{method:'POST',body:JSON.stringify(data)});toast('Estação salva no navegador e na servidor central.')}catch(err){toast('Estação salva somente neste navegador: '+err.message,true);log('Cadastro servidor central pendente',err.message,'aviso',id)}}else toast('Cadastro salvo no navegador.')}}
function saveBackup(){download('ecosense_backup_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({...state,adminKey:''},null,2),'application/json')}
async function importFile(file,station){if(!file)return toast('Selecione um arquivo CSV ou JSON.',true);try{if(file.size>15e6)throw Error('Arquivo acima de 15 MB. Divida em lotes menores.');let text=await file.text(),src=file.name.toLowerCase().endsWith('.csv')?parseCSV(text):getJSONrecords(JSON.parse(text));let n=await addRows(station,src);if(!src.length)throw Error('O arquivo não contém registros');if(!rows(state.stations.find(s=>s.id===station)).length)throw Error('Nenhuma leitura reconhecida. Verifique colunas de data, temperatura, umidade e pressão.');log('Arquivo importado',`${src.length} registros recebidos, ${n} novos`,'info',station);render();toast('Importação concluída: '+n+' novas medições.')}catch(e){toast(e.message,true)}}
function geoExport(){let geo={type:'FeatureCollection',features:state.stations.filter(s=>s.lat!=null&&s.lon!=null).map(s=>({type:'Feature',geometry:{type:'Point',coordinates:[s.lon,s.lat]},properties:{id:s.id,name:s.name,owner:s.owner,status:status(s)}}))};download('ecosense_estacoes.geojson',JSON.stringify(geo,null,2),'application/geo+json')}
async function geoImport(file){if(!file)return;try{let j=JSON.parse(await file.text()),features=j.features||[];let added=0;for(let f of features){if(f.geometry?.type!=='Point')continue;let [lon,lat]=f.geometry.coordinates||[];if(!Number.isFinite(+lon)||!Number.isFinite(+lat)||Math.abs(lat)>90||Math.abs(lon)>180)continue;let id=String(f.properties?.id||'geo_'+Math.random().toString(36).slice(2,8));if(state.stations.some(s=>s.id===id))continue;state.stations.push({id,name:f.properties?.name||id,lat:+lat,lon:+lon,owner:f.properties?.owner||'',endpoint:''});added++}save();log('Pontos importados',added+' estações georreferenciadas');render();toast(added+' pontos importados.')}catch(e){toast('GeoJSON inválido: '+e.message,true)}}
async function openMeteo(){let s=current();if(!s||s.lat==null||s.lon==null)return toast('Cadastre latitude e longitude da estação para consultar o Open-Meteo.',true);let el=$('#meteoResult');el.textContent='Consultando Open-Meteo...';try{let url=`https://api.open-meteo.com/v1/forecast?latitude=${encodeURIComponent(s.lat)}&longitude=${encodeURIComponent(s.lon)}&current=temperature_2m,relative_humidity_2m,surface_pressure&timezone=America%2FFortaleza`;let resp=await fetch(url);if(!resp.ok)throw Error('HTTP '+resp.status);let j=await resp.json(),d=j.current;if(!d)throw Error('Resposta sem dados correntes');el.innerHTML=`<div class="stat-list"><span>Temperatura externa</span><strong>${unit(d.temperature_2m,' °C')}</strong><span>Umidade externa</span><strong>${unit(d.relative_humidity_2m,' %')}</strong><span>Pressão externa</span><strong>${unit(d.surface_pressure,' hPa')}</strong><span>Horário Open-Meteo</span><strong>${html(d.time)}</strong></div>`;log('Referência consultada','Open-Meteo: '+s.name,'info',s.id)}catch(e){el.textContent='Falha ao consultar Open-Meteo: '+e.message;toast(e.message,true)}}
// Event delegation keeps controls operational after page transitions.
document.addEventListener('click',async e=>{let b=e.target.closest('[data-page],[data-go],[data-add-station],[data-edit],[data-delete],[data-focus],#syncTop,#themeToggle,#menuMobile,#coordsGo,#mapFit,#mapMeasure,#mapFullscreen,#geoExport,#geoImport,#importReadings,#backupJSON,#backupAll,#backupBtn,#syncSelected,#syncEveryone,#saveApi,#testApi,#loadStationsservidor central,#fetchMeteo,#exportCSV,#exportJSON,#expCSV,#expJSON,#downloadLogs,#reloadApp,#settingsSave');if(!b)return;try{if(b.dataset.page)return navigate(b.dataset.page);if(b.dataset.go)return navigate(b.dataset.go);if('addStation'in b.dataset)return stationModal();if(b.dataset.edit)return stationModal(state.stations.find(s=>s.id===b.dataset.edit));if(b.dataset.delete){let s=state.stations.find(s=>s.id===b.dataset.delete);if(!confirm('Excluir o cadastro '+s.name+'? O histórico ficará preservado neste navegador.'))return;state.stations=state.stations.filter(x=>x.id!==s.id);state.selected=state.stations[0]?.id;save();log('Cadastro excluído',s.name,'aviso',s.id);return render()}if(b.dataset.focus){state.selected=b.dataset.focus;save();navigate('mapa');let s=current();if(map&&s.lat!=null&&s.lon!=null)map.setView([s.lat,s.lon],15);return}switch(b.id){case'menuMobile':$('.sidebar').classList.toggle('show');break;case'syncTop':case'syncEveryone':if(CENTRAL_API)await refreshCentralSnapshot();else await syncAll();break;case'themeToggle':state.theme=state.theme==='light'?'dark':'light';applyTheme();break;case'coordsGo':{let v=$('#gotoCoords').value.match(/(-?\d+(?:\.\d+)?)\s*[,;]\s*(-?\d+(?:\.\d+)?)/);if(!v)return toast('Informe latitude e longitude decimal.',true);let lat=+v[1],lon=+v[2];if(Math.abs(lat)>90||Math.abs(lon)>180)return toast('Coordenadas inválidas.',true);map.setView([lat,lon],14);break}case'mapFit':{let pts=state.stations.filter(s=>s.lat!=null&&s.lon!=null).map(s=>[s.lat,s.lon]);if(pts.length)map.fitBounds(pts,{padding:[35,35],maxZoom:15});else toast('Nenhuma estação possui coordenadas.',true);break}case'mapFullscreen':{let el=document.querySelector('#mapLayout');if(!el)return;el.classList.toggle('expanded');setTimeout(()=>map?.invalidateSize({pan:false}),250);break}case'mapMeasure':{if(!map)return;toast('Clique em dois pontos do mapa para medir a distância.');let points=[];function click(ev){points.push(ev.latlng);if(points.length===2){let dist=map.distance(points[0],points[1]);L.polyline(points,{color:'#ffb523',weight:3}).addTo(map);map.off('click',click);toast('Distância: '+(dist>1000?unit(dist/1000,' km',2):unit(dist,' m',0)))}}map.on('click',click);break}case'geoExport':geoExport();break;case'geoImport':$('#geoFile').click();break;case'importReadings':await importFile($('#importFile').files[0],$('#importStation').value);break;case'backupJSON':case'backupAll':case'backupBtn':saveBackup();break;case'syncSelected':{if(CENTRAL_API){await refreshCentralSnapshot();toast('Resumo atualizado pela base servidor central.')}else{let n=await syncOne($('#syncStation').value);render();toast(n+' leituras adicionadas')}break}case'saveApi':{let url=$('#apiUrl').value.trim();if(url&&!url.startsWith('https://'))throw Error('API precisa de HTTPS.');state.apiUrl=url;state.adminKey=$('#adminKey').value;save();log('API configurada',url?'URL salva no navegador':'Conexão removida');toast('Conexão salva');break}case'testApi':{let j=await backend('/health',{method:'GET'});toast('API servidor central conectada: '+(j.service||'EcoSense'));break}case'loadStationsservidor central':{let result=await backend('/stations',{method:'GET'});let incoming=result.stations||[];let count=0;for(let remote of incoming){if(!state.stations.some(x=>x.id===remote.id)){state.stations.push({...remote,lat:remote.lat==null?null:Number(remote.lat),lon:remote.lon==null?null:Number(remote.lon)});count++}}save();render();toast(count+' estações novas importadas da servidor central.');break}case'fetchMeteo':await openMeteo();break;case'exportCSV':case'expCSV':exportRows('csv');break;case'exportJSON':case'expJSON':exportRows('json');break;case'downloadLogs':download('ecosense_logs.json',JSON.stringify(state.events,null,2),'application/json');break;case'reloadApp':location.reload();break;case'settingsSave':state.pollMinutes=Number($('#pollTime').value);state.theme=$('#lightSwitch').checked?'light':'dark';applyTheme();save();toast('Preferências salvas');break;}}catch(err){toast(err.message,true);log('Erro de operação',err.message,'aviso')}});
document.addEventListener('change',async e=>{let id=e.target.id;switch(id){case'mapLayer':mapMode=e.target.value;renderTiles();break;case'geoFile':await geoImport(e.target.files[0]);break;case'analysisPeriod':period=e.target.value;render();break;case'analysisMetric':metric=e.target.value;render();break;case'analysisStation':state.selected=e.target.value;save();render();break;case'logLevel':$('#logOutput').innerHTML=renderLogs(e.target.value);break}});
document.addEventListener('input',e=>{if(e.target.id==='mapSearch'){let term=e.target.value.toLowerCase();$$('#mapStations .station-card').forEach(el=>el.style.display=el.textContent.toLowerCase().includes(term)?'':'none')}});
function applyTheme(){
 const isLight=state.theme==='light';
 document.body.classList.toggle('light-mode',isLight);
 document.documentElement.style.colorScheme=isLight?'light':'dark';
 document.querySelector('meta[name="theme-color"]')?.setAttribute('content',isLight?'#f1f7f4':'#061919');
 const top=document.querySelector('#themeToggle');
 if(top){top.textContent=isLight?'☾':'☀';top.title=isLight?'Ativar tema escuro':'Ativar tema claro';top.setAttribute('aria-label',top.title);top.setAttribute('aria-pressed',String(isLight));}
 const mapButton=document.querySelector('#ecoThemeMap');
 if(mapButton){mapButton.innerHTML=isLight?'☾ <span>Escuro</span>':'☀ <span>Claro</span>';mapButton.title=isLight?'Ativar tema escuro':'Ativar tema claro';mapButton.setAttribute('aria-label',mapButton.title);mapButton.setAttribute('aria-pressed',String(isLight));}
 const toggle=document.querySelector('#lightSwitch');if(toggle)toggle.checked=isLight;
 save();
}
function tickClock(){$('#clock').textContent=new Date().toLocaleString('pt-BR',{timeZone:'America/Fortaleza',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}
// Inicialização segura: dados compartilhados serão carregados pelo app/cloud.js.
load();
state.stations=[{id:'loading',name:'Carregando estações...',lat:null,lon:null,endpoint:''}];
state.readings={};
state.selected='loading';
state.pollMinutes=0;
state.apiUrl='';
applyTheme();
tickClock();
setInterval(tickClock,30000);
render();
